#prisma 4.0
def group "world" {
    def object "sphere" {
        float2 position = (1.5,-2)
        float rotation = 0.25
        float2 scale = (2,3)
        bool visible = true
        int segments = 7
        spectrum reflectance = [0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5]
        float2 animPos = (0,0)
        float2 animPos.timeSamples = { 0: (0,0), 24: (100,0) (interp = held) }
    }
    def material "mat" {
        float ior = 1.5
        string texturePath = "brick.png"
        string label = "a \"quoted\"\ttab\nnewline"
    }
    def object "mesh" {
        float2[] points = [(0,0),(1.5,-2),(3,0)]
        int[] edges = [0,1,1,2,2,0]
        float[] width = [0.1,0.25,0.5]
    }
}
connect </world/sphere.inMaterial> = </world/mat.out>
